/// @title THE DIE - Keel ERC-721 collection
/// @notice Standards-compatible ERC-721 metadata with a Keel manifest pointer,
/// digest, marketplace poster, and stable HTML harness URL.
contract KEEL721 is
    ERC721,
    ERC2981,
    SafeAdminAccessControl,
    IKeelMintable,
    IKeelCampaignAuthorizer,
    IKeelMintCapacity,
    IKeel721Errors,
    IKeel721Events
{
    address internal immutable _pauseAuthority;

    using Strings for uint256;
    using JsonEscape for string;

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 private constant CAMPAIGN_CREATOR_ROLE = keccak256("CAMPAIGN_CREATOR_ROLE");
    bytes32 internal constant PRESENTATION_ROLE = keccak256("PRESENTATION_ROLE");
    bytes32 public constant PER_TOKEN_MINT_DATA_DOMAIN = keccak256("keel.per-token-mint-data.v1");
    /// @dev ERC-4906 assigns this identifier for metadata-update notifications.
    bytes4 private constant ERC4906_INTERFACE_ID = 0x49064906;

    struct Presentation {
        string manifestURI;
        bytes32 manifestDigest;
        string previewImageURI;
        bool configured;
        bool frozen;
    }

    uint256 public immutable maxSupply;
    uint256 public nextTokenId = 1;
    mapping(address manager => uint256 quantity) public override reservedStrikeCapacity;
    uint256 public override totalReservedStrikeCapacity;
    address public keelIndex;
    string public collectionDescription;
    string private _harnessBaseURI;
    bool public tokenOwnerCanEdit = true;
    bool public defaultPresentationFrozen;
    address public onchainHarnessBuilder;
    bool private _rawTokenURI;
    bytes32 private _onchainHarnessObjectId;
    bytes32 private _onchainHarnessDigest;
    bytes32 private _onchainTokenURIFragmentObjectId;
    bytes32 private _onchainTokenURIFragmentDigest;
    bytes internal _preparedTokenURIPrefix;
    bytes private _preparedTokenURISuffix;

    Presentation private _defaultPresentation;
    mapping(uint256 tokenId => Presentation presentation) internal _tokenPresentations;

    constructor(
        string memory name_,
        string memory symbol_,
        address admin,
        address mintManager,
        address registry,
        address royaltyReceiver,
        uint96 royaltyBps,
        uint256 maxSupply_
    ) ERC721(name_, symbol_) {
        _pauseAuthority = mintManager == address(0) ? admin : mintManager;
        if (admin == address(0)) revert ZeroAddress();
        if (maxSupply_ == 0) revert InvalidSupply();
        if (royaltyBps > 10_000 || (royaltyBps != 0 && royaltyReceiver == address(0))) revert InvalidRoyalty();

        maxSupply = maxSupply_;
        keelIndex = registry;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(CAMPAIGN_CREATOR_ROLE, admin);
        _grantRole(PRESENTATION_ROLE, admin);
        if (mintManager != address(0)) _grantRole(MINTER_ROLE, mintManager);
        if (royaltyReceiver != address(0) && royaltyBps != 0) _setDefaultRoyalty(royaltyReceiver, royaltyBps);

        if (registry != address(0)) IKeelPresentationRegistry(registry).registerCollection(address(this), admin);
    }

    function totalSupply() public view returns (uint256) {
        return nextTokenId - 1;
    }

    function isCampaignCreator(address account) external view override returns (bool) {
        return hasRole(CAMPAIGN_CREATOR_ROLE, account) || hasRole(DEFAULT_ADMIN_ROLE, account);
    }

    function reserveStrikeCapacity(uint256 quantity) external override onlyRole(MINTER_ROLE) {
        if (quantity == 0) revert InvalidQuantity();
        uint256 nextGlobalReservation = totalReservedStrikeCapacity + quantity;
        if (totalSupply() + nextGlobalReservation > maxSupply) revert SupplyExceeded();
        uint256 nextManagerReservation = reservedStrikeCapacity[msg.sender] + quantity;
        reservedStrikeCapacity[msg.sender] = nextManagerReservation;
        totalReservedStrikeCapacity = nextGlobalReservation;
        emit StrikeCapacityReserved({
            manager: msg.sender,
            quantity: quantity,
            managerTotal: nextManagerReservation,
            globalTotal: nextGlobalReservation
        });
    }

    function releaseStrikeCapacity(uint256 quantity) external override onlyRole(MINTER_ROLE) {
        uint256 managerReservation = reservedStrikeCapacity[msg.sender];
        if (quantity == 0 || quantity > managerReservation) revert InvalidReservation();
        uint256 nextManagerReservation = managerReservation - quantity;
        uint256 nextGlobalReservation = totalReservedStrikeCapacity - quantity;
        reservedStrikeCapacity[msg.sender] = nextManagerReservation;
        totalReservedStrikeCapacity = nextGlobalReservation;
        emit StrikeCapacityReleased({
            manager: msg.sender,
            quantity: quantity,
            managerTotal: nextManagerReservation,
            globalTotal: nextGlobalReservation
        });
    }

    function strikeFromManager(address to, uint256 quantity, bytes calldata data)
        external
        override
        onlyRole(MINTER_ROLE)
    {
        KeelPause.requireActive(_pauseAuthority, KeelPause.MINT_721);
        if (to == address(0)) revert ZeroAddress();
        if (quantity == 0) revert InvalidQuantity();
        uint256 firstTokenId = nextTokenId;
        uint256 next = firstTokenId + quantity;
        if (next - 1 > maxSupply) revert SupplyExceeded();
        _consumeManagerCapacity(msg.sender, quantity, next - 1);

        // Reserve the complete range before the first ERC721Receiver callback.
        // The receiver can knock; it cannot reach: a privileged recipient that
        // reenters finds the supply already spoken for and cannot overrun
        // maxSupply.
        nextTokenId = next;
        bytes[] memory slices;
        if (quantity > 1 && data.length != 0) {
            bytes32 domain;
            (domain, slices) = abi.decode(data, (bytes32, bytes[]));
            if (domain != PER_TOKEN_MINT_DATA_DOMAIN || slices.length != quantity) {
                revert InvalidPerTokenMintData();
            }
        }
        // Decode the batch once; each hook still receives its own mutable memory slice.
        for (uint256 i; i < quantity; ++i) {
            uint256 tokenId;
            // firstTokenId + quantity was checked above, and i is strictly smaller.
            unchecked {
                tokenId = firstTokenId + i;
            }
            bytes memory tokenMintData;
            if (quantity == 1) tokenMintData = data;
            else if (data.length != 0) tokenMintData = slices[i];
            _beforeManagerSafeMint(to, tokenId, msg.sender, tokenMintData);
            emit ManagerTokenStrikeData({
                recipient: to, tokenId: tokenId, tokenIndex: i, mintDataDigest: keccak256(tokenMintData)
            });
            _safeMint(to, tokenId);
        }
        emit ManagerStrikeData({recipient: to, firstTokenId: firstTokenId, quantity: quantity, data: data});
    }

    function adminStrike(address to, uint256 quantity) external virtual onlyRole(DEFAULT_ADMIN_ROLE) {
        KeelPause.requireActive(_pauseAuthority, KeelPause.MINT_721 | KeelPause.MINT_ADMIN);
        if (to == address(0)) revert ZeroAddress();
        if (quantity == 0) revert InvalidQuantity();
        uint256 firstTokenId = nextTokenId;
        uint256 next = firstTokenId + quantity;
        if (next - 1 > maxSupply || next - 1 + totalReservedStrikeCapacity > maxSupply) revert SupplyExceeded();
        nextTokenId = next;
        for (uint256 tokenId = firstTokenId; tokenId < next; ++tokenId) {
            _safeMint(to, tokenId);
        }
    }

    function setDefaultPresentation(
        string calldata manifestURI,
        bytes32 manifestDigest,
        string calldata previewImageURI,
        string calldata harnessBaseURI_
    ) external onlyRole(PRESENTATION_ROLE) {
        _requireAlternativePresentationRoute();
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        if (defaultPresentationFrozen) revert PresentationFrozen();
        _validatePresentation(manifestURI, manifestDigest);
        if (onchainHarnessBuilder != address(0) && bytes(harnessBaseURI_).length != 0) revert InvalidPresentation();
        _defaultPresentation = Presentation({
            manifestURI: manifestURI,
            manifestDigest: manifestDigest,
            previewImageURI: previewImageURI,
            configured: true,
            frozen: false
        });
        _harnessBaseURI = harnessBaseURI_;
        emit DefaultPresentationUpdated({
            manifestURI: manifestURI, manifestDigest: manifestDigest, previewImageURI: previewImageURI
        });
        emit HarnessBaseURIUpdated({harnessBaseURI: harnessBaseURI_});
        if (totalSupply() != 0) emit BatchMetadataUpdate({fromTokenId: 1, toTokenId: totalSupply()});
    }

    function setTokenPresentation(
        uint256 tokenId,
        string calldata manifestURI,
        bytes32 manifestDigest,
        string calldata previewImageURI
    ) external {
        _requireAlternativePresentationRoute();
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        address owner = ownerOf(tokenId);
        Presentation storage existing = _tokenPresentations[tokenId];
        if (existing.frozen) revert PresentationFrozen();
        if (!hasRole(PRESENTATION_ROLE, msg.sender) && !(tokenOwnerCanEdit && owner == msg.sender)) {
            revert UnauthorizedPresentationEditor();
        }
        _validatePresentation(manifestURI, manifestDigest);
        _tokenPresentations[tokenId] = Presentation({
            manifestURI: manifestURI,
            manifestDigest: manifestDigest,
            previewImageURI: previewImageURI,
            configured: true,
            frozen: false
        });
        emit TokenPresentationUpdated({
            tokenId: tokenId, manifestURI: manifestURI, manifestDigest: manifestDigest, previewImageURI: previewImageURI
        });
        emit MetadataUpdate({tokenId: tokenId});
    }

    function freezePresentation(uint256 tokenId) external {
        address owner = ownerOf(tokenId);
        if (!hasRole(PRESENTATION_ROLE, msg.sender) && owner != msg.sender) revert UnauthorizedPresentationEditor();
        Presentation storage presentation = _tokenPresentations[tokenId];
        if (presentation.frozen) revert PresentationFrozen();
        // Freeze the effective presentation, including a registry override even
        // when a non-frozen local token presentation was already configured.
        (string memory uri, bytes32 digest, string memory previewImageURI) = _resolvedPresentation(tokenId);
        presentation.manifestURI = uri;
        presentation.manifestDigest = digest;
        presentation.previewImageURI = previewImageURI;
        presentation.configured = true;
        presentation.frozen = true;
        emit PresentationFrozenForToken({tokenId: tokenId});
        _freezePresentationRoute(tokenId);
        emit MetadataUpdate({tokenId: tokenId});
    }

    function freezeDefaultPresentation() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _requireAlternativePresentationRoute();
        if (!_defaultPresentationAvailable()) revert InvalidPresentation();
        defaultPresentationFrozen = true;
        emit DefaultPresentationPermanentlyFrozen();
    }

    /// @notice Selects the exact immutable HTML object used by token metadata.
    /// Once the default presentation is frozen this route cannot be changed.
    function setOnchainHarness(address builder, bytes32 objectId, bytes32 digest) external onlyRole(PRESENTATION_ROLE) {
        _requireAlternativePresentationRoute();
        if (defaultPresentationFrozen) revert PresentationFrozen();
        if (builder.code.length == 0 || objectId == bytes32(0) || digest == bytes32(0)) {
            revert InvalidPresentation();
        }
        delete _preparedTokenURIPrefix;
        delete _preparedTokenURISuffix;
        _selectOnchainHarness(builder, objectId, digest, bytes32(0), bytes32(0), bytes32(0), bytes32(0));
    }

    /// @notice Atomically selects a pre-encoded inline viewer graph.
    /// @dev Studio uses this boundary so a partially completed wallet batch
    /// cannot leave the collection pointing at a fragment graph without also
    /// enabling the matching low-gas tokenURI read path.
    function setPreEncodedOnchainHarness(address builder, bytes32 objectId, bytes32 digest)
        external
        onlyRole(PRESENTATION_ROLE)
    {
        _requireAlternativePresentationRoute();
        if (defaultPresentationFrozen) revert PresentationFrozen();
        if (
            builder.code.length == 0 || objectId == bytes32(0) || digest == bytes32(0)
                || !IKeelHarnessBuilder(builder).preEncodedTokenURIFragmentValid(objectId, digest)
        ) revert InvalidPresentation();
        delete _preparedTokenURIPrefix;
        delete _preparedTokenURISuffix;
        _selectOnchainHarness(builder, objectId, digest, objectId, digest, bytes32(0), bytes32(0));
    }

    /// @notice Select an entirely build-time encoded ERC-721 tokenURI graph.
    /// @dev Intended for immutable 1/1 releases whose exact collection address,
    /// token id, manifest, image and seed are known before this call. The read
    /// path only copies the three committed Base64 slices; it never encodes,
    /// decodes, parses or rebuilds payload data.
    function setPreparedOnchainHarness(
        address builder,
        bytes32 objectId,
        bytes32 digest,
        bytes calldata encodedPrefix,
        bytes calldata encodedSuffix
    ) external onlyRole(PRESENTATION_ROLE) {
        _requireAlternativePresentationRoute();
        if (defaultPresentationFrozen) revert PresentationFrozen();
        if (
            maxSupply != 1 || !_preparedPresentationCompatible() || builder.code.length == 0 || objectId == bytes32(0)
                || digest == bytes32(0) || encodedPrefix.length == 0 || encodedSuffix.length == 0
                || !_preparedTokenURIEnvelopeValid(builder, objectId, digest, encodedPrefix, encodedSuffix)
        ) revert InvalidPresentation();
        _preparedTokenURIPrefix = encodedPrefix;
        _preparedTokenURISuffix = encodedSuffix;
        _selectOnchainHarness(builder, objectId, digest, objectId, digest, sha256(encodedPrefix), sha256(encodedSuffix));
    }

    function _selectOnchainHarness(
        address builder,
        bytes32 objectId,
        bytes32 digest,
        bytes32 fragmentObjectId,
        bytes32 fragmentDigest,
        bytes32 prefixDigest,
        bytes32 suffixDigest
    ) private {
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        _rawTokenURI = IKeelHarnessRegistration(builder).requireRegistration(objectId);
        onchainHarnessBuilder = builder;
        _onchainHarnessObjectId = objectId;
        _onchainHarnessDigest = digest;
        _onchainTokenURIFragmentObjectId = fragmentObjectId;
        _onchainTokenURIFragmentDigest = fragmentDigest;
        // An on-chain harness and a mutable network harness are mutually
        // exclusive: clear the base so no stale route can return later.
        _harnessBaseURI = "";
        emit HarnessBaseURIUpdated({harnessBaseURI: ""});
        emit OnchainHarnessUpdated({builder: builder, objectId: objectId, digest: digest});
        emit OnchainTokenURIFragmentUpdated({objectId: fragmentObjectId, digest: fragmentDigest});
        emit PreparedTokenURIFragmentsUpdated({prefixDigest: prefixDigest, suffixDigest: suffixDigest});
        if (totalSupply() != 0) emit BatchMetadataUpdate({fromTokenId: 1, toTokenId: totalSupply()});
    }

    function _preparedTokenURIEnvelopeValid(
        address builder,
        bytes32 objectId,
        bytes32 digest,
        bytes calldata encodedPrefix,
        bytes calldata encodedSuffix
    ) private view returns (bool) {
        try IKeelPercentTokenURIBuilder(builder)
            .preparedTokenURIEnvelopeValid(objectId, digest, encodedPrefix, encodedSuffix) returns (
            bool valid
        ) {
            return valid;
        } catch {
            return IKeelTokenURIEnvelope(address(IKeelHarnessBuilder(builder).keelHold()))
                    .preparedTokenURIEnvelopeValid(encodedPrefix, encodedSuffix)
                && IKeelHarnessBuilder(builder).preparedTokenURIFragmentValid(objectId, digest);
        }
    }

    function setCollectionDescription(string calldata value) external onlyRole(PRESENTATION_ROLE) {
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        collectionDescription = value;
        if (totalSupply() != 0) emit BatchMetadataUpdate({fromTokenId: 1, toTokenId: totalSupply()});
    }

    function setKeelIndex(address registry) external onlyRole(DEFAULT_ADMIN_ROLE) {
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        if (defaultPresentationFrozen) revert PresentationFrozen();
        keelIndex = registry;
        emit KeelIndexUpdated({registry: registry});
        if (totalSupply() != 0) emit BatchMetadataUpdate({fromTokenId: 1, toTokenId: totalSupply()});
    }

    function setTokenOwnerCanEdit(bool enabled) external onlyRole(DEFAULT_ADMIN_ROLE) {
        tokenOwnerCanEdit = enabled;
    }

    function setDefaultRoyalty(address receiver, uint96 feeNumerator) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (feeNumerator > 10_000) revert InvalidRoyalty();
        if (receiver == address(0) || feeNumerator == 0) _deleteDefaultRoyalty();
        else _setDefaultRoyalty(receiver, feeNumerator);
    }

    function defaultPresentationBinding() external view returns (bytes32) {
        return _defaultPresentationBinding();
    }

    /// @notice Read the immutable object route in one call instead of carrying
    /// four duplicate generated getters. Prepared prefix/suffix bytes are
    /// verified through `tokenURI` plus their digest event at configuration.
    function onchainPresentation()
        external
        view
        returns (
            address builder,
            bytes32 harnessObjectId,
            bytes32 harnessDigest,
            bytes32 fragmentObjectId,
            bytes32 fragmentDigest
        )
    {
        return (
            onchainHarnessBuilder,
            _onchainHarnessObjectId,
            _onchainHarnessDigest,
            _onchainTokenURIFragmentObjectId,
            _onchainTokenURIFragmentDigest
        );
    }

    function presentation(uint256 tokenId)
        external
        view
        returns (string memory manifestURI, bytes32 manifestDigest, string memory previewImageURI)
    {
        ownerOf(tokenId);
        (manifestURI, manifestDigest, previewImageURI) = _resolvedPresentation(tokenId);
        previewImageURI = _resolveImageURI(tokenId, previewImageURI);
    }

    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        if (_onchainTokenURIFragmentObjectId == bytes32(0)) {
            return string.concat("data:application/json;base64,", Base64.encode(bytes(tokenJSON(tokenId))));
        }
        ownerOf(tokenId);
        if (_preparedTokenURIPrefix.length != 0) {
            return IKeelHarnessBuilder(onchainHarnessBuilder)
                .preparedTokenURI(
                    _onchainTokenURIFragmentObjectId,
                    _onchainTokenURIFragmentDigest,
                    _preparedTokenURIPrefix,
                    _preparedTokenURISuffix
                );
        }
        (bytes memory prefix, bytes memory suffix) = _preEncodedTokenJSONEnvelope(tokenId);
        return IKeelHarnessBuilder(onchainHarnessBuilder)
            .preEncodedTokenURI(_onchainTokenURIFragmentObjectId, _onchainTokenURIFragmentDigest, prefix, suffix);
    }

    /// @notice Raw ERC-721 JSON for Keel-aware readers. The separate KeelSleeve
    /// adapter owns optional ERC-4804 routing instead of duplicating it here.
    function tokenJSON(uint256 tokenId) public view virtual returns (string memory) {
        ownerOf(tokenId);
        if (_preparedTokenURIPrefix.length != 0) revert PreparedTokenURIOnly();
        if (_onchainTokenURIFragmentObjectId != bytes32(0)) {
            (bytes memory prefix, bytes memory suffix) = _preEncodedTokenJSONEnvelope(tokenId);
            bytes memory middle = IKeelHarnessBuilder(onchainHarnessBuilder)
                .preEncodedTokenJSONMiddle(_onchainTokenURIFragmentObjectId, _onchainTokenURIFragmentDigest);
            return string(bytes.concat(prefix, middle, suffix));
        }
        (string memory manifestURI, bytes32 manifestDigest, string memory previewImageURI) =
            _resolvedPresentation(tokenId);
        string memory animationURL = _harnessURL(tokenId, manifestURI, manifestDigest);
        string memory imageURI = bytes(previewImageURI).length != 0 ? previewImageURI : manifestURI;
        imageURI = _resolveImageURI(tokenId, imageURI);
        return string.concat(
            _tokenJSONHead(tokenId, imageURI),
            '","animation_url":"',
            animationURL.escape(),
            _tokenJSONFooter(tokenId, manifestURI, manifestDigest)
        );
    }

    /// @notice Canonical data-only context supplied to the immutable on-chain
    /// harness wrapper. Base Keel collections intentionally return empty bytes;
    /// dynamic collections override the internal producer.
    function harnessContext(uint256 tokenId) public view returns (bytes memory) {
        ownerOf(tokenId);
        (, bytes32 manifestDigest,) = _resolvedPresentation(tokenId);
        return _resolvedHarnessContext(tokenId, manifestDigest);
    }

    /// @notice Announces an activated presentation from this collection's bound Index.
    /// @dev Publication alone does not change metadata. Empty collections need no refresh.
    function notifyIndexRevision(uint256 tokenId, bool tokenSpecific) external {
        if (msg.sender != keelIndex) revert UnauthorizedPresentationEditor();
        if (tokenSpecific) {
            if (_ownerOf(tokenId) != address(0) && !_tokenPresentations[tokenId].frozen) {
                emit MetadataUpdate(tokenId);
            }
        } else {
            uint256 supply = totalSupply();
            if (supply != 0) emit BatchMetadataUpdate(1, supply);
        }
    }

    /// @notice Authorizes a notification relay without granting it metadata editing rights.
    function setMetadataRelay(address relay) external {
        _checkRole(DEFAULT_ADMIN_ROLE, msg.sender);
        KeelMetadataSubscriptions.set(0, relay);
    }

    function metadataRelay() external view returns (address) {
        return KeelMetadataSubscriptions.relay(0);
    }

    /// @notice Follows a compact source getter; fixed-revision getters remain pinned.
    function subscribeMetadataDependency(
        address source,
        bytes calldata query,
        uint32 readGas,
        uint256 first,
        uint256 last
    ) external returns (uint256) {
        _checkRole(DEFAULT_ADMIN_ROLE, msg.sender);
        address relay = KeelMetadataSubscriptions.relay(0);
        if (relay == address(0)) revert KeelMetadataSubscriptions.InvalidMetadataRelay();
        return IKeelMetadataRelay(relay).subscribe(source, query, readGas, first, last);
    }

    function removeMetadataDependency(address relay, uint256 id) external {
        _checkRole(DEFAULT_ADMIN_ROLE, msg.sender);
        IKeelMetadataRelay(relay).unsubscribe(id);
    }

    /// @notice Emits collection-owned notifications for an authorized dependency change.
    function notifyDependencyMetadata(uint256 first, uint256 last) external {
        if (first > last) revert KeelMetadataSubscriptions.InvalidMetadataRange();
        KeelMetadataSubscriptions.requireRelay(0);
        uint256 mintedLast = nextTokenId - 1;
        if (first == 0) first = 1;
        if (last > mintedLast) last = mintedLast;
        if (first > last) return;
        if (first == last) emit MetadataUpdate(first);
        else emit BatchMetadataUpdate(first, last);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(ERC721, ERC2981, AccessControl)
        returns (bool)
    {
        return interfaceId == type(IKeelIndexMetadataReceiver).interfaceId || interfaceId == ERC4906_INTERFACE_ID
            || interfaceId == type(IKeelMintCapacity).interfaceId || interfaceId == type(IKeelMintable).interfaceId
            || interfaceId == type(IKeelCampaignAuthorizer).interfaceId || super.supportsInterface(interfaceId);
    }

    function _revokeRole(bytes32 role, address account) internal override(SafeAdminAccessControl) returns (bool) {
        if (role == MINTER_ROLE && reservedStrikeCapacity[account] != 0) revert OutstandingMintReservation();
        return super._revokeRole(role, account);
    }

    function _consumeManagerCapacity(address manager, uint256 quantity, uint256 supplyAfterMint) private {
        uint256 managerReservation = reservedStrikeCapacity[manager];
        if (managerReservation == 0) {
            if (supplyAfterMint + totalReservedStrikeCapacity > maxSupply) revert SupplyExceeded();
            return;
        }
        if (quantity > managerReservation) revert ReservedCapacityExceeded();

        uint256 nextManagerReservation = managerReservation - quantity;
        uint256 nextGlobalReservation = totalReservedStrikeCapacity - quantity;
        reservedStrikeCapacity[manager] = nextManagerReservation;
        totalReservedStrikeCapacity = nextGlobalReservation;
        emit StrikeCapacityConsumed({
            manager: manager,
            quantity: quantity,
            managerTotal: nextManagerReservation,
            globalTotal: nextGlobalReservation
        });
    }

    /// @dev Hook-enabled collections establish every mint-bound record here, after the complete
    ///      token range is reserved but before the ERC-721 receiver callback. The base is a no-op.
    function _beforeManagerSafeMint(address, uint256, address, bytes memory) internal virtual {}

    /// @dev Collection-specific metadata may append a valid JSON fragment that
    /// begins with a comma. The generic Keel path remains byte-for-byte empty.
    function _tokenJSONAttributes(uint256) internal view virtual returns (string memory) {
        return "";
    }

    function _resolvedPresentation(uint256 tokenId)
        private
        view
        returns (string memory manifestURI, bytes32 manifestDigest, string memory previewImageURI)
    {
        Presentation storage tokenPresentation = _tokenPresentations[tokenId];
        if (tokenPresentation.frozen) {
            return (tokenPresentation.manifestURI, tokenPresentation.manifestDigest, tokenPresentation.previewImageURI);
        }

        (string memory localURI, bytes32 localDigest, string memory localFallback) = _localPresentation(tokenId);
        previewImageURI = localFallback;
        address registry = keelIndex;
        if (registry != address(0)) {
            try IKeelPresentationRegistry(registry).activePresentation(address(this), tokenId) returns (
                string memory registryURI, bytes32 registryDigest, uint64
            ) {
                if (bytes(registryURI).length != 0 && registryDigest != bytes32(0)) {
                    return (registryURI, registryDigest, previewImageURI);
                }
            } catch {}
        }
        return (localURI, localDigest, previewImageURI);
    }

    function _localPresentation(uint256 tokenId)
        private
        view
        returns (string memory manifestURI, bytes32 manifestDigest, string memory previewImageURI)
    {
        Presentation storage tokenPresentation = _tokenPresentations[tokenId];
        if (tokenPresentation.configured) {
            return (tokenPresentation.manifestURI, tokenPresentation.manifestDigest, tokenPresentation.previewImageURI);
        }
        return
            (
                _defaultPresentation.manifestURI,
                _defaultPresentation.manifestDigest,
                _defaultPresentation.previewImageURI
            );
    }

    function _harnessURL(uint256 tokenId, string memory manifestURI, bytes32 manifestDigest)
        internal
        view
        returns (string memory)
    {
        if (onchainHarnessBuilder != address(0)) {
            // The inline animation_url must carry the same resolved context the
            // prepared route emits, or KEEL_SEED is never defined in the child
            // and a generative 1/1 draws something different on every open.
            bytes memory contextJSON = _resolvedHarnessContext(tokenId, manifestDigest);
            if (contextJSON.length != 0) {
                return KeelHarnessContextDispatch.harnessInlineURIWithContext(
                    onchainHarnessBuilder, _onchainHarnessObjectId, _onchainHarnessDigest, contextJSON
                );
            }
            return
                IKeelHarnessBuilder(onchainHarnessBuilder)
                    .harnessInlineURI(_onchainHarnessObjectId, _onchainHarnessDigest);
        }
        if (bytes(_harnessBaseURI).length == 0) return manifestURI;
        return Keel721MetadataFormatting.harnessURL(_harnessBaseURI, tokenId);
    }

    /// @dev Override in a dynamic collection to return canonical JSON no larger
    /// than the Keel builder's context ceiling. Empty bytes preserve the
    /// original context-free Keel route byte-for-byte.
    function _harnessContext(uint256, bytes32) internal view virtual returns (bytes memory) {
        return bytes("");
    }

    function _defaultPresentationBinding() internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256(bytes(_defaultPresentation.manifestURI)),
                _defaultPresentation.manifestDigest,
                keccak256(bytes(_defaultPresentation.previewImageURI)),
                _defaultPresentation.configured,
                defaultPresentationFrozen,
                onchainHarnessBuilder,
                _onchainHarnessObjectId,
                _onchainHarnessDigest,
                _onchainTokenURIFragmentObjectId,
                _onchainTokenURIFragmentDigest
            )
        );
    }

    /// @notice Capability gate for prepared fragments with live collection context.
    function supportsCompactTokenURI() external pure returns (bool) {
        return true;
    }

    function _tokenJSONFooter(uint256 tokenId, string memory manifestURI, bytes32 manifestDigest)
        private view returns (string memory)
    {
        return Keel721MetadataFormatting.footer(manifestURI, manifestDigest, _tokenJSONAttributes(tokenId));
    }

    function _tokenJSONHead(uint256 tokenId, string memory imageURI) private view returns (string memory) {
        return Keel721MetadataFormatting.head(name(), collectionDescription, tokenId, imageURI);
    }

    function _preEncodedTokenJSONEnvelope(uint256 tokenId)
        private
        view
        returns (bytes memory prefix, bytes memory suffix)
    {
        bool compact = _rawTokenURI;
        (string memory manifestURI, bytes32 manifestDigest, string memory previewImageURI) =
            _resolvedPresentation(tokenId);
        string memory imageURI = bytes(previewImageURI).length != 0 ? previewImageURI : manifestURI;
        imageURI = _resolveImageURI(tokenId, imageURI);
        prefix = bytes(
            string.concat(
                _tokenJSONHead(tokenId, imageURI),
                '","animation_url":"data:text/html',
                compact ? ";charset=utf-8," : ";base64,"
            )
        );
        // JSON permits leading whitespace; align only the legacy outer stream.
        if (!compact) {
            while (prefix.length % 3 != 0) prefix = bytes.concat(" ", prefix);
        }

        bytes memory contextJSON = _resolvedHarnessContext(tokenId, manifestDigest);
        suffix = bytes(
            string.concat(
                compact
                    ? string(IKeelRawTokenURIBuilder(onchainHarnessBuilder).contextURI(contextJSON))
                    : Base64.encode(_contextScriptTail(contextJSON)),
                _tokenJSONFooter(tokenId, manifestURI, manifestDigest)
            )
        );
    }

    /// @dev This is a document tail, not a URI fragment. The values and their
    ///      global slots are frozen so a module sees one immutable token
    ///      context, while the encoded tail keeps the entire animation payload
    ///      inside the RFC 4648 alphabet.
    function _contextScriptTail(bytes memory contextJSON) private pure returns (bytes memory) {
        return Keel721MetadataFormatting.contextScriptTail(contextJSON);
    }

    function _resolvedHarnessContext(uint256 tokenId, bytes32 manifestDigest)
        private
        view
        returns (bytes memory contextJSON)
    {
        contextJSON = _harnessContext(tokenId, manifestDigest);
        if (contextJSON.length != 0 || _onchainTokenURIFragmentObjectId == bytes32(0)) return contextJSON;
        return Keel721MetadataFormatting.defaultContext(tokenId, manifestDigest);
    }



    /// @dev Collection extensions resolve image references without changing the metadata schema.
    function _resolveImageURI(uint256, string memory fallbackURI) internal view virtual returns (string memory) {
        return fallbackURI;
    }

    function _defaultPresentationAvailable() internal view virtual returns (bool) {
        return _defaultPresentation.configured;
    }

    function _freezePresentationRoute(uint256) internal virtual {}

    /// @dev Optional collection profiles may close alternate presentation route configuration.
    function _requireAlternativePresentationRoute() internal view virtual {}

    function _preparedPresentationCompatible() internal view virtual returns (bool) {
        return true;
    }

    function _validatePresentation(string calldata manifestURI, bytes32 digest) private pure {
        if (bytes(manifestURI).length == 0 || digest == bytes32(0)) revert InvalidPresentation();
    }
}

