// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

/*──────────────── ⚓ KEEL · laid by RAVONUS · the keel holds ────────────────*/

import {KeelRouted721} from "./KeelRouted721.sol";

/// @dev Immutable runtime byte carrier. The constructor deliberately returns
/// the supplied bytes as code so the collection deployer can copy them without
/// embedding KEEL721 creation code in its own EIP-170-limited runtime.
contract KeelCreationCodeCarrier {
    constructor(bytes memory data) {
        assembly ("memory-safe") {
            return(add(data, 0x20), mload(data))
        }
    }
}

/*═════════════════════════════════════════════════════════════════════════

     CREATE2 CARRIER                          LAYER 01 · THE DIE
      ┌───────────────┐                   ─────────────────────────────
      │ creation code │▶ (predicted addr)  the ladle that carries the
      └───────────────┘                    molten die-steel to its slot.
     Carries the die's creation code so the factory stays under EIP-170.
     Every cast lands in the caller's own salt namespace - nobody casts
     a die into an address that was promised to someone else, and no
     front-runner squats on a predicted address before the pour arrives.

═════════════════════════════════════════════════════════════════════════*/

/// @notice Small CREATE2 carrier used by the size-bounded Sepolia factory.
/// Keeping the KEEL721 creation code here leaves the authorization factory
/// below the EIP-170 runtime bytecode limit.
contract KEEL721Deployer {
    address private immutable _creationCodeFirst;
    address private immutable _creationCodeSecond;
    uint32 private immutable _creationCodeFirstLength;
    uint32 private immutable _creationCodeSecondLength;
    bytes32 private immutable _creationCodeDigest;

    constructor() {
        bytes memory creation = type(KeelRouted721).creationCode;
        uint256 firstLength = (creation.length + 1) / 2;
        uint256 secondLength = creation.length - firstLength;
        _creationCodeFirst = address(new KeelCreationCodeCarrier(_slice(creation, 0, firstLength)));
        _creationCodeSecond = address(new KeelCreationCodeCarrier(_slice(creation, firstLength, secondLength)));
        _creationCodeFirstLength = uint32(firstLength);
        _creationCodeSecondLength = uint32(secondLength);
        _creationCodeDigest = keccak256(creation);
    }

    function deploy(
        bytes32 salt,
        string calldata name,
        string calldata symbol,
        address admin,
        address mintManager,
        address keelIndex,
        address royaltyReceiver,
        uint96 royaltyBps,
        uint256 maxSupply
    ) external returns (address collection) {
        bytes32 scopedSalt = keccak256(abi.encode(msg.sender, salt));
        bytes memory creation = _creationCode(
            abi.encode(name, symbol, admin, mintManager, keelIndex, royaltyReceiver, royaltyBps, maxSupply)
        );
        assembly ("memory-safe") {
            collection := create2(0, add(creation, 0x20), mload(creation), scopedSalt)
        }
        if (collection == address(0)) revert();
    }

    /// @notice Predicts within the caller's private CREATE2 namespace. A
    /// third party therefore cannot front-run a factory's exact collection
    /// address by calling this shared deployer directly.
    function predict(
        bytes32 salt,
        string calldata name,
        string calldata symbol,
        address admin,
        address mintManager,
        address keelIndex,
        address royaltyReceiver,
        uint96 royaltyBps,
        uint256 maxSupply
    ) external view returns (address predicted) {
        bytes memory creation = _creationCode(
            abi.encode(name, symbol, admin, mintManager, keelIndex, royaltyReceiver, royaltyBps, maxSupply)
        );
        bytes32 scopedSalt = keccak256(abi.encode(msg.sender, salt));
        bytes32 digest = keccak256(abi.encodePacked(bytes1(0xff), address(this), scopedSalt, keccak256(creation)));
        predicted = address(uint160(uint256(digest)));
    }

    function creationCodeHash() external view returns (bytes32) {
        return _creationCodeDigest;
    }

    function _creationCode(bytes memory constructorArguments) private view returns (bytes memory creation) {
        uint256 firstLength = _creationCodeFirstLength;
        uint256 secondLength = _creationCodeSecondLength;
        uint256 codeLength = firstLength + secondLength;
        creation = new bytes(codeLength + constructorArguments.length);
        address first = _creationCodeFirst;
        address second = _creationCodeSecond;
        assembly ("memory-safe") {
            let output := add(creation, 0x20)
            extcodecopy(first, output, 0, firstLength)
            extcodecopy(second, add(output, firstLength), 0, secondLength)
            let source := add(constructorArguments, 0x20)
            let destination := add(output, codeLength)
            let end := add(source, mload(constructorArguments))
            for {} lt(source, end) {
                source := add(source, 0x20)
                destination := add(destination, 0x20)
            } {
                mstore(destination, mload(source))
            }
        }
    }

    function _slice(bytes memory source, uint256 offset, uint256 length) private pure returns (bytes memory output) {
        output = new bytes(length);
        for (uint256 index; index < length; index += 32) {
            assembly ("memory-safe") {
                mstore(add(add(output, 0x20), index), mload(add(add(source, 0x20), add(offset, index))))
            }
        }
    }
}

