// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import {KEEL721} from "./KEEL721.sol";
import {Keel721Presentation} from "./Keel721Presentation.sol";
import {KeelPause} from "@keel/keel-kernel/libraries/KeelPause.sol";

/*
    /==[ KEEL :: ROUTED DIE ]====================================\
    |  [##] =======> [ IMAGE | METADATA ] <======= [##]           |
    \___________________________________________________________/

    ────────────────────────────────────────────⚒──
     R A V O N U S
     he laid the keel. hell cannot pull it loose.
    ────────────────────────────────────────────────
*/

/// @notice KEEL721 with a shared image-reference and custom metadata-URI module.
/// @dev Keeps the presentation extension optional for other KEEL721-derived contracts.
contract KeelRouted721 is KEEL721 {
    Keel721Presentation public presentationModule;

    constructor(
        string memory name_,
        string memory symbol_,
        address admin,
        address mintManager,
        address registry,
        address royaltyReceiver,
        uint96 royaltyBps,
        uint256 maxSupply_
    ) KEEL721(name_, symbol_, admin, mintManager, registry, royaltyReceiver, royaltyBps, maxSupply_) {}

    /// @notice Selects the shared presentation module before minting begins.
    /// @dev The binding is permanent so a replacement cannot bypass frozen token routes.
    function setPresentationModule(address module) external onlyRole(DEFAULT_ADMIN_ROLE) {
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        if (defaultPresentationFrozen) revert PresentationFrozen();
        if (totalSupply() != 0 || address(presentationModule) != address(0) || module.code.length == 0) {
            revert InvalidPresentation();
        }
        presentationModule = Keel721Presentation(module);
        emit PresentationModuleSet({module: module});
    }

    /// @notice The bound module asks the collection to authorize a presentation edit.
    /// @dev Metadata notices revert with the module transaction if validation or storage fails.
    function authorizePresentation(uint256 tokenId, address account, bool image) external {
        if (msg.sender != address(presentationModule)) revert UnauthorizedPresentationEditor();
        KeelPause.requireActive(_pauseAuthority, KeelPause.VIEWERS);
        if (image && _preparedTokenURIPrefix.length != 0) revert PreparedTokenURIOnly();
        if (tokenId == 0) {
            if (defaultPresentationFrozen) revert PresentationFrozen();
            _checkRole(PRESENTATION_ROLE, account);
            if (totalSupply() != 0) emit BatchMetadataUpdate({fromTokenId: 1, toTokenId: totalSupply()});
        } else {
            address owner = ownerOf(tokenId);
            if (_tokenPresentations[tokenId].frozen) revert PresentationFrozen();
            if (!hasRole(PRESENTATION_ROLE, account) && !(tokenOwnerCanEdit && owner == account)) {
                revert UnauthorizedPresentationEditor();
            }
            emit MetadataUpdate({tokenId: tokenId});
        }
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        if (address(presentationModule) != address(0)) {
            (bool overridden, string memory uri) = presentationModule.tokenURI(address(this), tokenId);
            if (overridden) {
                ownerOf(tokenId);
                return uri;
            }
        }
        return super.tokenURI(tokenId);
    }

    function _resolveImageURI(uint256 tokenId, string memory fallbackURI)
        internal
        view
        override
        returns (string memory)
    {
        if (address(presentationModule) == address(0)) return fallbackURI;
        return presentationModule.imageURI(address(this), tokenId, fallbackURI);
    }

    function _defaultPresentationAvailable() internal view override returns (bool) {
        if (super._defaultPresentationAvailable()) return true;
        if (address(presentationModule) == address(0)) return false;
        (bool configured,) = presentationModule.tokenURI(address(this), 0);
        return configured;
    }

    function _freezePresentationRoute(uint256 tokenId) internal override {
        if (address(presentationModule) != address(0)) presentationModule.freeze(tokenId);
    }

    function _preparedPresentationCompatible() internal view override returns (bool) {
        return address(presentationModule) == address(0);
    }
}

