// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {JsonEscape} from "@keel/keel-kernel/libraries/JsonEscape.sol";

/*
    /==[ KEEL :: SIGNAL CODEC ]=================================\
    |  [ JSON ] >>> |||||| >>> [ COLLECTION TRANSMISSION ]      |
    \__________________________________________________________/
    ────────────────────────────────────────────⚒──
     R A V O N U S
     he laid the keel. hell cannot pull it loose.
    ────────────────────────────────────────────────
*/

/// @notice Shared serialization keeps feature-rich collection implementations deployable.
/// @dev Linked library calls preserve the calling collection's address and chain context.
/// No storage is read or written here; formatting matches the collection's original bytes.
library Keel721MetadataFormatting {
    using JsonEscape for string;
    using Strings for uint256;

    function head(string memory name, string memory description, uint256 id, string memory image)
        external pure returns (string memory)
    {
        return string.concat('{"name":"', name.escape(), " #", id.toString(),
            '","description":"', description.escape(), '","image":"', image.escape());
    }

    function footer(string memory uri, bytes32 digest, string memory attributes)
        external pure returns (string memory)
    {
        return string.concat('\",\"keel_schema\":\"keel-manifest@2\",\"keel_manifest\":\"', uri.escape(),
            '\",\"keel_manifest_digest\":\"', Strings.toHexString(uint256(digest), 32), '\"', attributes, "}");
    }

    function contextScriptTail(bytes memory contextJSON) external pure returns (bytes memory) {
        return bytes.concat(bytes('<script>const j=atob("'), bytes(Base64.encode(contextJSON)), bytes(
            '"),c=Object.freeze(JSON.parse(j));__KEEL_CONTEXT__=c;__KEEL_ONCHAIN_CONTEXT__=Object.freeze({json:j});KEEL_SEED=c.derivedTokenSeed??c.tokenSeed??c.seed</script>'
        ));
    }

    function defaultContext(uint256 tokenId, bytes32 manifestDigest) external view returns (bytes memory) {
        bytes32 seed = keccak256(abi.encode("keel.inline-token-seed@1", block.chainid, address(this), tokenId, manifestDigest));
        return bytes(string.concat('{"protocol":"keel-context@1","chainId":"', block.chainid.toString(),
            '","collection":"', Strings.toHexString(uint256(uint160(address(this))), 20),
            '","tokenId":"', tokenId.toString(), '","derivedTokenSeed":"', Strings.toHexString(uint256(seed), 32),
            '","manifestDigest":"', Strings.toHexString(uint256(manifestDigest), 32), '"}'));
    }

    function harnessURL(string memory value, uint256 tokenId) external view returns (string memory) {
        bytes memory base = bytes(value);
        // The caller handles the empty-base fallback before selecting this route.
        bytes1 last = base[base.length - 1];
        string memory separator = last == bytes1(uint8(0x3f)) || last == bytes1(uint8(0x26)) ? "" : _containsQuestion(base) ? "&" : "?";
        return string.concat(value, separator, "chainId=", block.chainid.toString(), "&contract=",
            Strings.toHexString(uint256(uint160(address(this))), 20), "&tokenId=", tokenId.toString());
    }

    function _containsQuestion(bytes memory value) private pure returns (bool) {
        for (uint256 i; i < value.length; ++i) {
            if (value[i] == bytes1(uint8(0x3f))) return true;
        }
        return false;
    }
}
